<script setup>
import { onMounted, ref, watch } from 'vue'; import { useI18n } from 'vue-i18n'; import { Moon, Sun, Monitor, Plus, Trash2, KeyRound } from 'lucide-vue-next'; import { invoke } from '../services/tauri'
const {t,locale}=useI18n(); const settings=ref({theme:'system',language:locale.value,fimEnabled:false}); const models=ref([]); const draft=ref({id:'',name:'',provider:'OpenAI-compatible',baseUrl:'https://api.openai.com/v1',model:'gpt-4o-mini',isDefault:false});
onMounted(async()=>{settings.value=await invoke('settings_get'); locale.value=settings.value.language; models.value=await invoke('model_list')}); async function save(){settings.value=await invoke('settings_update',{settings:settings.value}); applyTheme(settings.value.theme)} function applyTheme(v){if(v==='system')document.documentElement.dataset.theme=matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light';else document.documentElement.dataset.theme=v;localStorage.setItem('tiny-note-theme',document.documentElement.dataset.theme)} function add(){draft.value={id:crypto.randomUUID(),name:'',provider:'OpenAI-compatible',baseUrl:'https://api.openai.com/v1',model:'gpt-4o-mini',isDefault:models.value.length===0}} async function saveModel(){if(!draft.value.name||!draft.value.model)return;await invoke('model_upsert',{profile:{...draft.value,apiKeyConfigured:false},apiKey:draft.value.apiKey});models.value=await invoke('model_list');draft.value={id:'',name:'',provider:'OpenAI-compatible',baseUrl:'https://api.openai.com/v1',model:'gpt-4o-mini',isDefault:false}} async function remove(id){await invoke('model_delete',{id});models.value=await invoke('model_list')}; watch(()=>settings.value.language,v=>locale.value=v)
</script>
<template><div class="settings-page"><div class="page-title"><div class="eyebrow">{{t('settings')}}</div><h1>{{t('settings')}}</h1><p>让 Tiny Note 适合你的工作节奏。</p></div><section class="settings-section"><h2>{{t('theme')}}</h2><div class="theme-options"><button :class="{selected:settings.theme==='light'}" @click="settings.theme='light';save()"><Sun :size="18"/>{{t('light')}}</button><button :class="{selected:settings.theme==='dark'}" @click="settings.theme='dark';save()"><Moon :size="18"/>{{t('dark')}}</button><button :class="{selected:settings.theme==='system'}" @click="settings.theme='system';save()"><Monitor :size="18"/>{{t('system')}}</button></div></section><section class="settings-section"><h2>{{t('language')}}</h2><select v-model="settings.language" @change="save"><option value="zh-CN">简体中文</option><option value="en">English</option></select></section><section class="settings-section"><div class="setting-heading"><div><h2>{{t('fim')}}</h2><p>{{t('fimHint')}}。首次开启会发起外部 API 请求并可能产生费用。</p></div><label class="switch"><input v-model="settings.fimEnabled" type="checkbox" @change="save"/><span></span></label></div></section><section class="settings-section"><div class="setting-heading"><div><h2>{{t('model')}}</h2><p>API Key 由系统凭据存储保护，Tiny Note 不会读取明文到页面。</p></div><button class="primary-button" @click="add"><Plus :size="15"/>{{t('addModel')}}</button></div><div v-for="m in models" :key="m.id" class="model-row"><div class="model-avatar"><KeyRound :size="16"/></div><div><strong>{{m.name}}</strong><small>{{m.provider}} · {{m.model}}</small></div><span class="model-status">{{m.apiKeyConfigured?t('configured'):t('notConfigured')}}</span><button class="icon-button danger" @click="remove(m.id)"><Trash2 :size="15"/></button></div><div v-if="draft.id" class="model-form"><input v-model="draft.name" :placeholder="t('model')"/><input v-model="draft.baseUrl" :placeholder="t('baseUrl')"/><input v-model="draft.model" :placeholder="t('modelName')"/><input v-model="draft.apiKey" type="password" :placeholder="t('apiKey')"/><div><button class="secondary-button" @click="draft.id=''">{{t('cancel')}}</button><button class="primary-button" @click="saveModel">{{t('save')}}</button></div></div></section></div></template>
